public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    backtrack(nums, new ArrayList<>(), used, result);
    return result;
}

private void backtrack(int[] nums, List<Integer> current, boolean[] used, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, current, used, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize candidate substrings
    int minIndex = 0;
    for (int i = 1; i < strings.size(); i++) {
        if (strings.get(i).length() < strings.get(minIndex).length()) {
            minIndex = i;
        }
    }
    String minStr = strings.get(minIndex);
    if (minStr.isEmpty()) {
        return 0;
    }
    int minLen = minStr.length();
    // Iterate lengths from longest to shortest
    for (int len = minLen; len > 0; len--) {
        java.util.Set<String> candidates = new java.util.HashSet<>();
        // generate all substrings of current length from the shortest string
        for (int start = 0; start + len <= minStr.length(); start++) {
            candidates.add(minStr.substring(start, start + len));
        }
        // check each candidate
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean allMatch = true;
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(rev))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    int deposits = 0;

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // flood fill using stack (DFS)
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int i = 0; i < 8; i++) {
                        int nr = cr + dr[i];
                        int nc = cc + dc[i];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }

    return deposits;
}

