}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }

        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // Left half is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // Right half is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removeCount = (int) (n * 0.05);
    // If removal amount is zero (array too small), simply compute average of all elements
    if (removeCount == 0) {
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / (double) n;
    }
    // Sort the array to remove smallest and largest 5%
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * removeCount;
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        // Invalid input: cannot perform pairing.
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        // Odd number of elements cannot be fully paired.
        return false;
    }
    // Count frequencies of remainders modulo k.
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // Ensure non‑negative remainder
        freq[rem]++;
    }
    // Remainder 0 elements must be paired among themselves.
    if (freq[0] % 2 != 0) {
        return false;
    }
    // For even k, remainder k/2 elements must also pair among themselves.
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    // For the remaining remainders, each r must match k - r.
    for (int r = 1; r < k - r; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list for the tree
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // Recursive DFS that returns the time needed to collect apples in subtree rooted at node
    // and return to that node.
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int total = 0;
    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) continue;
        int childTime = dfs(neighbor, node, graph, hasApple);
        // If the child subtree has any apples or the child itself has an apple,
        // we need to traverse the edge to the child and back.
        if (childTime > 0 || hasApple[neighbor]) {
            total += childTime + 2;
        }
    }
    return total;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    int maxSize = 0;
    for (int num : nums) {
        for (int size = maxSize; size >= 0; size--) {
            java.util.HashSet<Integer> curr = dp[size];
            java.util.HashSet<Integer> next = dp[size + 1];
            for (int sum : curr) {
                next.add(sum + num);
            }
        }
        maxSize++;
    }
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n == 0) {
            int target = (int) (totalSum * k / n);
            if (dp[k].contains(target)) return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0;
    }
    int first = cost[0];
    int second = cost[1];
    for (int i = 2; i < n; i++) {
        int current = Math.min(first, second) + cost[i];
        first = second;
        second = current;
    }
    return Math.min(first, second);
}

public int uniqueMorseRepresentations(String[] words) {
    // Mapping of each letter to its Morse code representation
    String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..",   // a-i
        ".---", "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", // j-r
        "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."          // s-z
    };

    if (words == null || words.length == 0) {
        return 0;
    }

    java.util.Set<String> uniqueTransformations = new java.util.HashSet<>();

    for (String word : words) {
        if (word == null) {
            continue; // skip null entries
        }

        StringBuilder transformed = new StringBuilder();

        for (char ch : word.toCharArray()) {
            int index = ch - 'a';
            if (index < 0 || index >= morse.length) {
                // Skip characters outside 'a'-'z'; alternatively, could throw an exception
                continue;
            }
            transformed.append(morse[index]);
        }

        uniqueTransformations.add(transformed.toString());
    }

    return uniqueTransformations.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    if (k > s.length()) {
        return false;
    }
    int totalCodes = 1 << k;
    Set<Integer> seen = new HashSet<>(totalCodes);
    int mask = totalCodes - 1;
    int code = 0;
    // Build the first window
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen.add(code);
    // Slide through the string
    for (int i = k; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        seen.add(code);
    }
    return seen.size() == totalCodes;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    // Validate input parameters
    if (sentence == null || searchWord == null) {
        return -1;
    }

    // Trim the sentence to avoid leading/trailing spaces affecting word positions
    sentence = sentence.trim();
    if (sentence.isEmpty()) {
        return -1;
    }

    // Split the sentence into words using whitespace as delimiter
    // The regex "\\s+" handles multiple consecutive spaces
    String[] words = sentence.split("\\s+");
    int wordCount = words.length;

    // Iterate over words and check if searchWord is a prefix
    for (int i = 0; i < wordCount; i++) {
        String word = words[i];
        if (word.startsWith(searchWord)) {
            // Words are 1-indexed as per problem statement
            return i + 1;
        }
    }

    // No word had searchWord as a prefix
    return -1;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int unmatchedOpen = 0;  // number of '(' that need a matching ')'
    int insertClose = 0;    // number of ')' that need a leading '('

    for (char c : s.toCharArray()) {
        if (c == '(') {
            unmatchedOpen++;
        } else if (c == ')') {
            unmatchedOpen--;
            if (unmatchedOpen < 0) {
                // we have a ')' without a matching '('
                insertClose++;
                unmatchedOpen = 0;
            }
        }
    }

    // unmatchedOpen now holds remaining '(' that need ')' at the end
    return insertClose + unmatchedOpen;
}

