    }
    return Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0; // no Fibonacci numbers needed for non‑positive k
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is enough for all k up to 2^31‑1
    fib[0] = 1;
    fib[1] = 1;
    int size = 2; // number of Fibonacci values stored
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }
    // Greedily subtract the largest usable Fibonacci number
    int remaining = k;
    int count = 0;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return (k > factors.size()) ? -1 : factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if current and top are opposite case of same letter
            if (Math.abs(current - top) == 32) {
                stack.deleteCharAt(len - 1); // remove the bad pair
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
