private int dfs(int index, Set<String> used, String s) {
    if (index == s.length()) return 0;
    int maxParts = 0;
    for (int end=index+1; end<=s.length(); end++){
        String sub = s.substring(index, end);
        if (!used.contains(sub)){
            used.add(sub);
            int parts = 1 + dfs(end, used, s);
            if (parts > maxParts) maxParts = parts;
            used.remove(sub);
        }
    }
    return maxParts;
}

