public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        int newOnes = (ones ^ num) & ~twos;
        int newTwos = (twos ^ num) & ~newOnes;
        ones = newOnes;
        twos = newTwos;
    }
    return ones;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    // Include 0 if it lies within the range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    // Use BFS to generate stepping numbers starting from 1 to 9
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

