public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    try {
        // Check for duplicate points
        int[] p0 = points[0];
        int[] p1 = points[1];
        int[] p2 = points[2];
        if (p0 == null || p1 == null || p2 == null) {
            return false;
        }
        int x0 = p0[0], y0 = p0[1];
        int x1 = p1[0], y1 = p1[1];
        int x2 = p2[0], y2 = p2[1];
        if ((x0 == x1 && y0 == y1) ||
            (x0 == x2 && y0 == y2) ||
            (x1 == x2 && y1 == y2)) {
            return false;
        }
        // Use cross product to determine if points are collinear
        int cross = (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0);
        return cross != 0;
    } catch (Exception e) {
        // Any exception in accessing array elements results in false
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    long[] ugly = new long[n];
    ugly[0] = 1L;

    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;

    for (int i = 1; i < n; i++) {
        long next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = next;

        if (next == next2) {
            i2++;
            next2 = ugly[i2] * 2L;
        }
        if (next == next3) {
            i3++;
            next3 = ugly[i3] * 3L;
        }
        if (next == next5) {
            i5++;
            next5 = ugly[i5] * 5L;
        }
    }

    long result = ugly[n - 1];
    if (result > Integer.MAX_VALUE || result < Integer.MIN_VALUE) {
        throw new ArithmeticException("Result exceeds int range.");
    }
    return (int) result;
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int max = 1;
    int current = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            current++;
        } else {
            current = 1;
            prev = c;
        }
        if (current > max) {
            max = current;
        }
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current += 1;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int num : nums) {
        frequency.put(num, frequency.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrt = (int) Math.sqrt(n);
    if (sqrt * sqrt == n) return 1;
    for (int i = 1; i <= sqrt; i++) {
        int remainder = n - i * i;
        int rSqrt = (int) Math.sqrt(remainder);
        if (rSqrt * rSqrt == remainder) return 2;
    }
    int temp = n;
    while (temp % 4 == 0) temp /= 4;
    if (temp % 8 == 7) return 4;
    return 3;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringTokenizer st = new StringTokenizer(s, " ");
    StringBuilder result = new StringBuilder();
    while (st.hasMoreTokens()) {
        String word = st.nextToken();
        for (int i = word.length() - 1; i >= 0; i--) {
            result.append(word.charAt(i));
        }
        if (st.hasMoreTokens()) {
            result.append(' ');
        }
    }
    return result.toString();
}
